mapper.select:
select id, type, geometry, properties, create_time as createTime, create_user as createUser, industry_code as industryCode, annotation_Name as annotationName from vm_air_map_annotation_t where delete_flag = 0
and annotation_Name like CONCAT(CONCAT('%', #{queryName}), '%')
${dataScope}

mapper.update:
update vm_air_map_annotation_t
set delete_flag = 1,
    update_time = NOW(),
    update_user = #{updateUser}
where id = #{id}

update vm_air_map_annotation_t
set geometry        = #{geometry},
    properties      = #{properties},
    annotation_Name = #{annotationName}
where id = #{id}

mapper.select:
select count(id)
from vm_air_map_annotation_t
where type = #{type} ${dataScope}

