UPDATE vm_air_map_point_t
point_name = #{pointName}, longitude = #{longitude}, latitude = #{latitude}, task_record_id = #{taskRecordId}, uav_name = #{uavName}, task_record_name = #{taskRecordName}, photo_id = #{photoId}, time_created = #{timeCreated}, photo_url = #{photoUrl}, task_access_node = #{photoAccessNode}, tenant_id = #{tenantId}, industry_code = #{industryCode}, photo_json_info = #{photoJsonInfo}, update_time = NOW(), update_user = #{updateUser}, app_ver_code = #{appVerCode}, point_type = #{pointType}, status = #{status}, photo_height = #{photoHeight},
WHERE id = #{id}

UPDATE vm_air_map_point_t
    set delete_flag = 1
where id = #{id}

mapper.select:
SELECT id, point_name as pointName, longitude, latitude, uav_name as uavName, task_record_id as taskRecordId, task_record_name as taskRecordName, photo_id as photoId, time_created as timeCreated, photo_url as photoUrl, photo_json_info as photoJsonInfo, task_access_node as photoAccessNode, tenant_id as tenantId, industry_code as industryCode, create_time as createTime, create_user as createUser, update_time as updateTime, update_user as updateUser, app_ver_code as appVerCode, point_type as pointType, status, device_code as deviceCode, uav_code as uavCode, photo_height as photoHeight FROM vm_air_map_point_t WHERE delete_flag = '0'
AND point_name LIKE CONCAT('%', #{pointName}, '%')
and DATE_FORMAT(time_created,'%Y-%m-%d %H:%i:%s') >= #{timeCreatedStartTime} and DATE_FORMAT(time_created,'%Y-%m-%d %H:%i:%s') <= #{timeCreatedEndTime}
and device_code = #{deviceCode}
and task_record_id = #{taskRecordId}
${dataScope} ORDER BY create_time DESC

select count(id) from vm_air_map_point_t
where point_name = #{pointName} and delete_flag = 0

    AND id !=  #{id}

${dataScope}

select flight_route_id as flightRouteId,extra_field as kmzJson,type as type from vm_air_line_t t where delete_flag = 0 and flight_main_type = 0
and device_code in
#{item}

SELECT t.flight_route_id as flightRouteId, flight_route_name as flightRouteName, kmz_storage_path as kmzUrl, type as type, t.device_code as deviceCode, (case when length(IFNULL(rel.device_name, '')) = 0 then dt.device_name else rel.device_name end ) as deviceName, t.update_time as modifiedTime, warning_type_id as warningTypeId, CASE WHEN col.collect_id IS NOT NULL THEN 0 ELSE 1 END as colStatus, kmz_file_name as kmzFileName, kmz_access_path as kmzAccessUrl, t.create_time as createTime, (case when length(IFNULL(relnest.device_name, '')) = 0 then dtl.device_name else relnest.device_name end ) as uavNestName, t.create_user as createUser, t.update_user as updateUser, t.update_time as updateTime, t.access_node as accessNode FROM vm_air_line_t t LEFT JOIN vm_uav_device_info_t dt ON t.start_nest_code = dt.device_code LEFT JOIN vm_uav_nest_device_info dtl ON dtl.device_code = t.start_nest_code LEFT JOIN vm_air_line_col_t col ON t.flight_route_id = col.collect_id AND col.user_id = #{userId} and status = 0 LEFT JOIN vm_tenant_device_common_rel_t relnest ON relnest.device_code = dtl.device_code and relnest.tenant_id = #{tenantId} and relnest.industry_code = #{industryCode} and relnest.delete_flag = '0' and relnest.device_type = 4 LEFT JOIN vm_tenant_device_common_rel_t rel ON rel.device_code = dt.device_code and rel.tenant_id = #{tenantId} and rel.industry_code = #{industryCode} and rel.delete_flag = '0' and rel.device_type = 1 where t.delete_flag = 0 and t.flight_main_type = 0 and ( t.device_code in (select device_code from vm_order_uav_nest_devices where tenant_id = t.tenant_id and industry_code = t.industry_code and ord_status in (0,1,2) ) ) and t.flight_route_id in
#{item}
${dataScope} order by t.create_time desc

select dt.device_code as uavCode,
       (case when length(IFNULL(rel.device_name, '')) = 0 then dt.device_name else rel.device_name end ) as uavName,
        dt.uav_nest_code as uavNestCode,
       (case when length(IFNULL(relnest.device_name, '')) = 0 then dtl.device_name else relnest.device_name end ) as uavNestName
from vm_uav_device_info_t dt
join vm_uav_nest_device_info dtl on dt.uav_nest_code = dtl.device_code
 LEFT JOIN vm_tenant_device_common_rel_t rel ON rel.device_code = dt.device_code
    and rel.tenant_id = #{tenantId}
    and rel.industry_code = #{industryCode}
    and rel.delete_flag = '0'
    and rel.device_type = 1
LEFT JOIN vm_tenant_device_common_rel_t relnest ON relnest.device_code = dtl.device_code
and relnest.tenant_id = #{tenantId}
and relnest.industry_code = #{industryCode}
and relnest.delete_flag = '0'
and relnest.device_type = 4
where dt.delete_flag = 0 and (
    dtl.device_code in

    #{item}

    or
    dt.device_code in

    #{item}

    )

